/* ===== Schul-Held: alle Fächer, Klasse 5–13, KI-Aufträge, Erklären, Endlos-Training, Diktat, Videos, Bücher, Aufräumen =====
   Nur Funktionsdeklarationen (route() läuft, bevor Top-Level-Code dieser Datei ausgeführt würde). */
function subjById(id){return SUBJ.find(x=>x.id===id)}
function klBtns(cur,cls){let h='';for(let k=5;k<=13;k++)h+=`<button class="chip ${cls}${k===cur?' on':''}" data-k="${k}">${k}</button>`;return h}
function hubInit(){
  SUBJ.forEach(s=>{TOPICS['gen_'+s.id]={id:'gen_'+s.id,title:s.name+' – Endlos-Training',tags:s.name+' endlos training übungen',sub:s,chap:{t:'Endlos-Training',i:'♾️'},
    s:[['♾️ Endlos-Training',`Hier kommen immer neue Aufgaben für <b>${s.name}</b> – passend zu deiner Klasse (einstellbar unter „Klasse ändern“). Aufgaben aus niedrigeren Klassen werden zur Wiederholung mit eingemischt.`],['💡 Tipp','Für Aufgaben genau zu deinem Thema: „Übungen aus dem Netz“ (Lexikon-Lückentexte) oder einen KI-Auftrag bauen und das Paket einfügen.']],
    ex:[],extra:[],vgen:()=>genQ(s.id)}});
}
/* ---------- Klasse ---------- */
function klassePage(){
  setNav('home');
  app().innerHTML=`<a class="back" href="#/">← Start</a><h1>🎓 Meine Klasse</h1><p class="lead">Die Klasse bestimmt, wie schwer das Endlos-Training ist, welche Erklärungen und Videos gesucht werden und was in den KI-Aufträgen steht.</p><div class="chips">${klBtns(klasse(),'klc')}</div><p class="hint">Die fertigen Lektionen in der App (Mathe, Englisch, Deutsch) sind für Klasse 5. Für alle anderen Klassen und Fächer helfen Endlos-Training, Lexikon-Erklärungen, Videos und KI-Pakete.</p>`;
  $('#app').insertAdjacentHTML('beforeend','<h2>🏫 Schulform</h2>'+sfChips('ksf2'));document.querySelectorAll('.ksf2').forEach(b=>b.onclick=()=>{sfSet(b.dataset.v);klassePage()});
  document.querySelectorAll('.klc').forEach(b=>b.onclick=()=>{try{localStorage.setItem('sh5kl',b.dataset.k)}catch(e){}klassePage()});
}
/* ---------- Fach-Seite: Werkzeuge + eigene Sachen ---------- */
function subjTools(s,si){
  const lang=s.id==='deutsch'||s.id==='englisch',fl=LANG_SUBJ[s.id],a=(h,i,t,sm,x)=>`<a class="act" href="${h}"${x||''}>${i}<b>${t}</b><small>${sm}</small></a>`;
  return `<p class="hint">🎓 Klasse ${klasse()} · <a href="#/klasse" style="color:var(--ac)">ändern</a></p><div class="acts">
  ${a('#/quiz/'+s.id,'🎯','Quiz','tippen, schreiben, gemischt')}
  ${fl||lang?a('#/s/hoeren/'+(fl||(s.id==='englisch'?'en':'de')),'👂','Hören','Aussprache & Hörverstehen'):''}
  ${s.id==='deutsch'?a('#/lesen','📖','Lesen lernen','Silben farbig'):''}
  ${a('#/ws/'+s.id,'🖨️','Arbeitsblatt','zum Ausdrucken')}
  ${a('#/practice/gen_'+s.id,'♾️','Endlos-Training','immer neue Aufgaben')}
  ${a('#/explain/'+s.id,'📖','Erklär mir …','Folien, einfach oder ausführlich')}
  ${a('#/online/'+s.id,'🌐','Übungen aus dem Netz','Lückentexte zu jedem Thema')}
  ${a('#/videos/'+s.id,'🎬','Erklärvideos','passend zur Klasse')}
  ${a('#/ki/'+s.id,'🤖','KI-Auftrag','Foto → KI → App')}
  ${a('#/books/'+s.id,'📚','Bücher','ISBN · freie Bücher')}
  ${a('#/lib/'+s.id,'📁','Meine Dateien','eBook, PDF, Bilder ansehen')}
  ${lang?a('#/dictat/'+s.id,'✍️','Diktat','hören und schreiben'):''}
  ${s.id!=='mathe'?a('#/vocab','🔤',s.id==='englisch'?'Vokabeln':'Begriffe','Karten · Schreiben · Verbinden',` onclick="vst().f='${s.id}';vst().src='all'"`):''}
  </div>`}
function subjMine(si){
  const l=MINE.filter(x=>x.s===si),b=myBooks().filter(x=>x.subj===SUBJ[si].id);
  return (l.length?`<h2>🗂️ Meine Sachen</h2>`+l.map(x=>`<a class="row" href="#/t/m_${x.id}"><span>${esc(x.name)}<small>${esc(x.book||'')}</small></span><em>${starStr('m_'+x.id)}</em></a>`).join(''):'')+
   (b.length?`<h2>📚 Meine Bücher</h2>`+b.map(x=>`<a class="row" href="#/books/${SUBJ[si].id}"><span>${esc(x.title)}<small>${esc(x.author||'')} ${x.isbn?'· ISBN '+esc(x.isbn):''}</small></span><em>${x.read?'📖':''}</em></a>`).join(''):'')+
   `<p class="hint" style="margin-top:14px">Noch mehr Stoff? <a href="#/ki/${SUBJ[si].id}" style="color:var(--ac)">KI-Auftrag bauen</a> oder <a href="#/packs" style="color:var(--ac)">fertige Pakete</a>.</p>`}

/* ---------- KI-Auftrag ---------- */
function kiRules(id,k){
  const R={mathe:`Löse jede Aufgabe der Seite mit Rechenweg (in "explain") und erfinde ähnliche Aufgaben mit anderen Zahlen. Meist Typ "num". Passend zu Klasse ${k}.`,
   englisch:`Gib in "vocab" ALLE Vokabeln der Seite als ["englisch","deutsch"] aus. Aufgaben: Lückensätze, Übersetzen, Grammatik, Wortschatz. Fragen auf Deutsch, Beispielsätze auf Englisch. In "dictation" 8 englische Sätze mit den Vokabeln.`,
   deutsch:`Aufgaben zu Rechtschreibung, Grammatik, Wortarten, Satzgliedern, Zeitformen, Zeichensetzung${k>=8?', Textanalyse, Stilmittel, Argumentation':''}. In "dictation" 10 Diktatsätze mit typischen Schwierigkeiten (ie, ss/ß, Dehnungs-h, das/dass, Groß-/Kleinschreibung).`,
   biologie:'Verständnisfragen, Fachbegriffe, Abläufe in die richtige Reihenfolge, Lückensätze.',physik:'Verständnisfragen und Rechenaufgaben mit Formel, Einheit und Rechenweg in "explain" (Antwort als Zahl in der angegebenen Einheit).',
   chemie:'Fachbegriffe, Elemente/Symbole, Reaktionen, Stoffeigenschaften, Rechenaufgaben mit Rechenweg.',informatik:'Begriffe, Binärzahlen, Algorithmen, Code-Ausgaben vorhersagen, Datenschutz.',
   politik:'Begriffe, Institutionen, Rechte und Pflichten, Demokratie, Fallbeispiele. Neutral und ohne Meinung.',geschichte:'Jahreszahlen, Personen, Ursachen und Folgen, Epochen, Reihenfolgen.',
   musik:'Noten, Rhythmus, Instrumente, Komponisten, Epochen, Fachbegriffe.',erdkunde:'Länder, Hauptstädte, Klima, Karten, Landschaften, Fachbegriffe, Ursachen und Folgen.'};
  return (R[id]||'')+(id!=='englisch'&&id!=='mathe'?' Gib die wichtigsten Fachbegriffe in "vocab" als ["Begriff","kurze Erklärung"] aus.':'')}
function SF_LIST(){return['Grundschule','Hauptschule','Realschule','Sekundarschule','Gesamtschule','Gymnasium','Förderschule','Berufskolleg']}
function schulform(){try{return localStorage.getItem('sh5sf')||''}catch(e){return''}}
function sfSet(v){try{localStorage.setItem('sh5sf',v)}catch(e){}}
function sfText(){const f=schulform();return f?f+' NRW':'Schule in NRW'}
function sfChips(cls){const f=schulform();return `<div class="chips">${SF_LIST().map(x=>`<button class="chip ${cls}${x===f?' on':''}" data-v="${x}">${x}</button>`).join('')}</div>`+(f?'':'<p class="hint" style="color:#b45309;font-weight:700">⚠️ Bitte zuerst die Schulform wählen – damit die KI das richtige Niveau trifft.</p>')}
function sfLevel(){const f=schulform();return f==='Gymnasium'?' Niveau: Gymnasium (anspruchsvoll, mehr Transferaufgaben).':f==='Förderschule'?' Niveau: Förderschule (sehr kleine Schritte, einfache Sprache, viele Beispiele).':f==='Hauptschule'?' Niveau: Hauptschule (einfache Sprache, alltagsnah, kleine Schritte).':f==='Grundschule'?' Niveau: Grundschule (sehr einfach, kindgerecht).':f==='Berufskolleg'?' Niveau: Berufskolleg (berufsbezogen, praxisnah).':f?' Niveau: '+f+'.':''}
function kiPrompt(o){
  const s=subjById(o.f)||SUBJ[2],k=o.k,book=o.book?` Buch: ${o.book}${o.page?', Seite '+o.page:''}.`:'',top=o.topic?` Thema: ${o.topic}.`:'',kids=k<=7?'sehr einfach und kindgerecht, kurze Sätze, Beispiele aus dem Alltag':k<=10?'verständlich mit Beispielen':'fachlich genau, auf Oberstufen-Niveau, mit Fachsprache';
  const what={foto:`Ich schicke dir ein Foto einer Schulbuch- oder Arbeitsheftseite. Lies die Seite, erkenne NUR das Wichtige (ignoriere Seitenzahlen, Lautschrift, Kopfzeilen, Werbung) und baue daraus ein Lernpaket: Zusammenfassung, 6–10 Erklär-Folien und 30–40 Aufgaben.`,
   erkl:`Erkläre das Thema mit 8–12 Erklär-Folien (${kids}). Jede Folie: Überschrift, 2–5 Sätze, passendes Emoji. Danach 15 Aufgaben zum Überprüfen.`,
   ueb:`Erstelle 40 abwechslungsreiche Übungsaufgaben mit Tipps und Erklärungen, von leicht nach schwer. Dazu 3 kurze Erklär-Folien mit dem Wichtigsten.`,
   dikt:`Erstelle ein Diktat: 15 Sätze in "dictation" (passend zu Klasse ${k}), dazu 10 Rechtschreib-Aufgaben in "tasks" und 2 Folien mit den Rechtschreibregeln.`,
   arbeit:`Erstelle eine Übungs-Klassenarbeit: 25 Aufgaben wie in einer echten Arbeit (gemischt, von leicht nach schwer) mit Lösungen und Erklärungen, dazu 5 Folien zum Wiederholen.`,
   vok:`Ich schicke dir ein Foto einer Vokabel- oder Begriffsseite. Gib ALLE Wörter/Begriffe in "vocab" aus und baue 20 Aufgaben dazu.`}[o.type]||'';
  return `Du bist eine freundliche, geduldige Lehrkraft. Fach: ${s.name}, Klasse ${k} (${sfText()}).${sfLevel()}${book}${top}
${what}
Regeln für das Fach: ${kiRules(s.id,k)}
Sprache: Deutsch, ${kids}.

Antworte NUR mit gültigem JSON in einem Code-Kasten, ohne Text davor oder danach, genau in dieser Form:
{"subject":"${s.name}","book":"${o.book||''}","klasse":${k},"title":"kurzer Titel${o.page?' (S. '+o.page+')':''}","key":"Das Wichtigste als Stichpunkte, eine Zeile pro Punkt",
"slides":[{"title":"Überschrift","text":"Erklärung in 2–5 Sätzen","emoji":"💡"}],
"vocab":[["Wort/Begriff","Übersetzung/Erklärung"]],
"dictation":["Satz 1.","Satz 2."],
"tasks":[{"type":"choice","q":"Frage","options":["richtig","falsch","falsch"],"answer":"richtig","hint":"Tipp","explain":"Erklärung"},
{"type":"text","q":"Frage","answer":"kurze Antwort","alt":["andere richtige Schreibweise"],"hint":"Tipp","explain":"Erklärung"},
{"type":"num","q":"Rechenaufgabe","answer":"42","hint":"Tipp","explain":"Rechenweg"}]}
Wichtig: "subject" genau "${s.name}". Bei "choice" 3–4 Optionen, "answer" steht wörtlich in "options". Bei "num" ist "answer" nur eine Zahl. Felder, die nicht passen, als leere Liste [] lassen. Gültiges JSON: doppelte Anführungszeichen, keine Kommas am Ende.`}
function kiPage(f){
  setNav('ki');const st=window._ki||(window._ki={f:f||'deutsch',type:'foto',ai:'chatgpt',k:klasse(),book:'',page:'',topic:''});if(f)st.f=f;
  const AIs={chatgpt:['ChatGPT','https://chatgpt.com/'],gemini:['Gemini','https://gemini.google.com/app'],claude:['Claude','https://claude.ai/new'],copilot:['Copilot','https://copilot.microsoft.com/']};
  const T=[['foto','📷','Paket aus Foto'],['vok','🔤','Vokabeln/Begriffe aus Foto'],['erkl','📖','Erklärung mit Folien'],['ueb','✏️','40 Übungen zu Thema'],['arbeit','📝','Klassenarbeit üben'],['dikt','✍️','Diktat']];
  const needTopic=['erkl','ueb','arbeit','dikt'].includes(st.type),needFoto=['foto','vok'].includes(st.type),s=subjById(st.f);
  if(!st.book&&s.book)st.book=['mathe','englisch','deutsch'].includes(s.id)&&st.k===5?BOOKS_(SUBJ.indexOf(s)):'';
  app().innerHTML=`<h1>🤖 KI-Auftrag bauen</h1><p class="lead">Die App schreibt den Auftrag für die KI. Du kopierst ihn, gibst ihn (mit Foto) an ChatGPT, Gemini oder Claude und fügst die Antwort hier wieder ein.</p>
  <h2>1. Fach</h2><div class="chips">${SUBJ.map(x=>`<button class="chip kf${x.id===st.f?' on':''}" data-f="${x.id}">${x.icon} ${x.name}</button>`).join('')}</div>
  <h2>2. Klasse</h2><div class="chips">${klBtns(st.k,'kk')}</div>
  <h2>Schulform</h2>${sfChips('ksf')}
  <h2>3. Was soll die KI bauen?</h2><div class="chips">${T.map(t=>`<button class="chip kt${t[0]===st.type?' on':''}" data-t="${t[0]}">${t[1]} ${t[2]}</button>`).join('')}</div>
  ${needTopic?`<input id="kto" class="ans" placeholder="Thema, z. B. Photosynthese, Bruchrechnung, Simple Past" value="${esc(st.topic)}">`:''}
  <div class="row2"><input id="kbo" class="ans" placeholder="Buch (optional)" value="${esc(st.book)}"><input id="kpa" class="ans" placeholder="Seite (optional)" value="${esc(st.page)}" style="max-width:130px"></div>
  <h2>4. Welche KI?</h2><div class="chips">${Object.keys(AIs).map(a=>`<button class="chip ka${a===st.ai?' on':''}" data-a="${a}">${AIs[a][0]}</button>`).join('')}</div>
  <h2>5. Auftrag kopieren</h2><textarea id="kpr" class="ans" rows="9" readonly>${esc(kiPrompt(st))}</textarea>
  <div class="row2"><button id="kcp" class="go">📋 Text kopieren</button><a class="btn" target="_blank" rel="noopener" href="${AIs[st.ai][1]}">↗ ${AIs[st.ai][0]} öffnen</a></div><div id="kmsg" class="hint"></div>
  <div class="card" style="padding:12px;margin:12px 0"><b>So geht's:</b><ol style="margin:6px 0 0 18px;line-height:1.6">
  <li>Auf <b>📋 Text kopieren</b> tippen.</li><li><b>${AIs[st.ai][0]} öffnen</b> (App oder Webseite).</li>
  ${needFoto?'<li>Foto der Buchseite anhängen: auf <b>📎 / +</b> tippen → Kamera oder Galerie.</li>':''}
  <li>Ins Eingabefeld lange drücken → <b>Einfügen</b> → senden.</li><li>Warten, bis die KI fertig ist. Am Code-Kasten auf <b>Kopieren</b> tippen (oder den ganzen Text markieren und kopieren).</li>
  <li>Zurück in die App → <b>📥 Antwort einfügen</b>. Das Paket landet unter „Meine Sachen“ im Fach ${esc(s.name)}.</li></ol></div>
  <a class="go" style="display:block;text-align:center;background:#6d28d9;border-color:#6d28d9" href="#/import">📥 Antwort der KI einfügen</a>
  <p class="hint">Tipp: Gib jeder Seite einen eigenen Titel (Seite angeben) – gleicher Titel ersetzt das alte Paket, neuer Titel kommt dazu. Keine Fotos von Personen oder persönliche Daten an die KI schicken.</p>`;
  const up=()=>{const t=$('#kto');if(t)st.topic=t.value;st.book=$('#kbo').value;st.page=$('#kpa').value;$('#kpr').value=kiPrompt(st)};
  ['#kto','#kbo','#kpa'].forEach(i=>{const e=$(i);if(e)e.oninput=up});
  document.querySelectorAll('.kf').forEach(b=>b.onclick=()=>{up();st.f=b.dataset.f;st.book='';kiPage()});
  document.querySelectorAll('.kk').forEach(b=>b.onclick=()=>{up();st.k=+b.dataset.k;kiPage()});
  document.querySelectorAll('.kt').forEach(b=>b.onclick=()=>{up();st.type=b.dataset.t;kiPage()});
  document.querySelectorAll('.ksf').forEach(b=>b.onclick=()=>{up();sfSet(b.dataset.v);kiPage()});
  document.querySelectorAll('.ka').forEach(b=>b.onclick=()=>{up();st.ai=b.dataset.a;kiPage()});
  $('#kcp').onclick=()=>{up();if(!schulform()){$('#kmsg').textContent='⚠️ Bitte erst oben die Schulform wählen.';document.querySelector('.ksf').scrollIntoView({behavior:'smooth',block:'center'});return}copyText($('#kpr').value).then(ok=>{$('#kmsg').textContent=ok?'✔ Kopiert! Jetzt die KI öffnen und einfügen.':'Bitte den Text im Feld lange drücken → Alles auswählen → Kopieren.'})};
}
async function copyText(t){try{await navigator.clipboard.writeText(t);return true}catch(e){try{const a=document.createElement('textarea');a.value=t;document.body.appendChild(a);a.select();const ok=document.execCommand('copy');a.remove();return ok}catch(x){return false}}}

/* ---------- Lexikon holen (Klexikon = einfach, Wikipedia = ausführlich) ---------- */
function wikiApi(src){return src==='klexikon'?'https://klexikon.zum.de/api.php':src==='simple'?'https://simple.wikipedia.org/w/api.php':'https://de.wikipedia.org/w/api.php'}
function wikiBase(src){return src==='klexikon'?'https://klexikon.zum.de/wiki/':src==='simple'?'https://simple.wikipedia.org/wiki/':'https://de.wikipedia.org/wiki/'}
async function wikiFetch(src,q,random){
  const api=wikiApi(src),u=random?`${api}?action=query&format=json&origin=*&generator=random&grnnamespace=0&grnlimit=1&prop=extracts&explaintext=1&exsectionformat=wiki&exchars=6000`
    :`${api}?action=query&format=json&origin=*&generator=search&gsrsearch=${encodeURIComponent(q)}&gsrlimit=1&prop=extracts&explaintext=1&exsectionformat=wiki&exchars=12000`;
  const r=await fetch(u),j=await r.json(),p=Object.values((j.query&&j.query.pages)||{})[0];if(!p||!p.extract)return null;
  return{title:p.title,text:p.extract,url:wikiBase(src)+encodeURIComponent(p.title.replace(/ /g,'_')),src}}
function textToSlides(text,max){
  const out=[];let head='Überblick';
  text.split(/\n+/).forEach(par=>{par=par.trim();if(!par)return;const h=par.match(/^=+\s*(.*?)\s*=+$/);if(h){head=h[1];return}
    if(/^(Einzelnachweise|Literatur|Weblinks|Siehe auch|Anmerkungen|References|See also)$/i.test(head))return;
    const sents=par.match(/[^.!?]+[.!?]+(\s|$)/g)||[par];let cur='';
    sents.forEach(x=>{if((cur+x).length>420&&cur){out.push([head,cur.trim()]);cur=''}cur+=x});if(cur.trim())out.push([head,cur.trim()])});
  return out.slice(0,max||14)}
function sentencesOf(text){return(text.replace(/=+[^=\n]+=+/g,' ').replace(/\s+/g,' ').match(/[A-ZÄÖÜ][^.!?]{20,180}[.!?]/g)||[])}

/* ---------- Erklär mir … (Folien) ---------- */
function explainPage(f,q){
  setNav('home');f=f||'deutsch';const s=subjById(f)||SUBJ[2],k=klasse();
  app().innerHTML=`<a class="back" href="#/s/${s.id}">← ${s.name}</a><h1>📖 Erklär mir …</h1><p class="lead">Gib ein Thema ein. Die App holt eine Erklärung aus dem Kinderlexikon (einfach) oder aus Wikipedia (ausführlich) und macht daraus Folien.</p>
  <div class="chips">${SUBJ.map(x=>`<button class="chip ef${x.id===f?' on':''}" data-f="${x.id}">${x.icon} ${x.name}</button>`).join('')}</div>
  <input id="eq" class="ans" placeholder="z. B. Photosynthese, Römer, Strom, Vulkan" value="${esc(q||'')}"><div class="row2"><button id="es" class="go" data-m="klexikon">🧒 Einfach (Klexikon)</button><button id="ew" class="go" data-m="wiki" style="background:#0f766e;border-color:#0f766e">🎓 Ausführlich (Wikipedia)</button></div>
  <div id="eout"></div>`;
  document.querySelectorAll('.ef').forEach(b=>b.onclick=()=>explainPage(b.dataset.f,$('#eq').value));
  const run=async m=>{const qq=$('#eq').value.trim();if(!qq)return;const o=$('#eout');o.innerHTML='<p class="lead">Suche …</p>';
    try{let d=await wikiFetch(m,qq);if(!d&&m==='klexikon'){d=await wikiFetch('wiki',qq);if(d)o.innerHTML='<p class="hint">Im Kinderlexikon nichts gefunden – hier aus Wikipedia:</p>'}
      if(!d){o.innerHTML='<p class="lead">Nichts gefunden. Probiere ein anderes Wort oder lass dir das Thema von der KI erklären.</p>'+`<a class="go" style="display:block;text-align:center" href="#/ki/${s.id}" onclick="window._ki=Object.assign(window._ki||{},{f:'${s.id}',type:'erkl',topic:${JSON.stringify(qq).replace(/"/g,'&quot;')},k:klasse(),ai:'chatgpt',book:'',page:''})">🤖 KI-Auftrag „Erklärung mit Folien“</a>`;return}
      showSlides(o,d,s,m==='klexikon'?8:14)}catch(e){o.innerHTML='<p class="lead">Keine Verbindung zum Internet?</p>'}};
  $('#es').onclick=()=>run('klexikon');$('#ew').onclick=()=>run('wiki');$('#eq').onkeydown=e=>{if(e.key==='Enter')run(k<=7?'klexikon':'wiki')};
  if(q)run(k<=7?'klexikon':'wiki');
}
function showSlides(o,d,s,max){
  const sl=textToSlides(d.text,max);if(!sl.length){o.innerHTML='<p class="lead">Der Artikel ist leer.</p>';return}let i=0;
  const draw=()=>{const x=sl[i];o.innerHTML=`<div class="stop"><div class="dots">${sl.map((_,n)=>`<i class="${n<=i?'on':''}"></i>`).join('')}</div><span>${i+1}/${sl.length}</span></div>
    <div class="slide in" style="--c:${s.color}"><small>${s.icon} ${esc(d.title)}</small><h2>${esc(x[0])}</h2><div class="sbody">${esc(x[1])}</div></div>
    <div class="snav"><button id="sp" ${i?'':'disabled'}>◀</button><button id="sv">🔊 Vorlesen</button><button id="sn" class="go" ${i<sl.length-1?'':'disabled'}>▶</button></div>
    <div class="acts"><button class="act" id="sx">💾<b>Als Sache speichern</b><small>mit Folien &amp; Übungen</small></button><button class="act" id="so">✏️<b>Üben dazu</b><small>Lückentexte endlos</small></button>
    <a class="act" href="#/videos/${s.id}?q=${encodeURIComponent(d.title)}" onclick="window._vq=${JSON.stringify(d.title).replace(/"/g,'&quot;')}">🎬<b>Videos</b><small>zum Thema</small></a><a class="act" target="_blank" rel="noopener" href="${d.url}">↗<b>Ganzer Artikel</b><small>${d.src==='klexikon'?'Klexikon':'Wikipedia'}</small></a></div>
    <p class="hint">Quelle: ${d.src==='klexikon'?'Klexikon – das Kinderlexikon':'Wikipedia'} (CC BY-SA).</p>`;
    $('#sp').onclick=()=>{i--;draw()};$('#sn').onclick=()=>{i++;draw()};$('#sv').onclick=()=>speak(x[0]+'. '+x[1],'de-DE');
    let x0=null;const el=o.querySelector('.slide');el.ontouchstart=e=>x0=e.touches[0].clientX;el.ontouchend=e=>{if(x0==null)return;const dd=e.changedTouches[0].clientX-x0;x0=null;if(dd<-50&&i<sl.length-1){i++;draw()}if(dd>50&&i){i--;draw()}};
    $('#sx').onclick=()=>{const si=SUBJ.indexOf(s),it=packImport({subject:s.name,book:'Lexikon',title:d.title+' (Erklärung)',key:sl.map(z=>z[1]).join('\n').slice(0,6000),slides:sl.map(z=>({title:z[0],text:z[1],emoji:s.icon})),tasks:[],vocab:[]});go('#/t/m_'+it.id)};
    $('#so').onclick=()=>startCloze(d,s)};
  draw()}

/* ---------- Übungen aus dem Netz (Lückentexte, endlos) ---------- */
function clozeGen(text,lang){
  const sents=sentencesOf(text).filter(x=>x.split(' ').length>=6),stop=new Set('Der Die Das Ein Eine Diese Dieser Dieses Sie Er Es Wir Ihr Man Auch Dann Doch Aber Oder Und Wenn Weil Damit Heute Viele Einige Andere Jahre Jahr Zeit Teil Beispiel'.split(' '));
  const cand=s=>(s.match(lang==='en'?/\b[a-z]{6,}\b/g:/(?<=\s)[A-ZÄÖÜ][a-zäöüß]{4,}\b/g)||[]).filter(w=>!stop.has(w));
  const pool=[...new Set(sents.flatMap(cand))];if(sents.length<2||pool.length<4)return null;
  return()=>{for(let n=0;n<20;n++){const s=pick(sents),c=cand(s);if(!c.length)continue;const w=pick(c),o=shuffle(pool.filter(x=>x!==w)).slice(0,3);
    return Q('Welches Wort fehlt?<br><i>'+esc(s.replace(new RegExp('(^|[^A-Za-zÄÖÜäöüß])'+w+'(?![A-Za-zÄÖÜäöüß])'),'$1_____'))+'</i>',w,{kind:'choice',opts:shuffle([w,...o]),steps:esc(s)})}
    return Q('Welches Wort passt?',pool[0],{kind:'choice',opts:shuffle(pool.slice(0,4))})}}
function startCloze(d,s){
  const g=clozeGen(d.text,s.id==='englisch'?'en':'de');if(!g){alert('Der Text ist zu kurz für Übungen.');return}
  const id='on_'+Date.now().toString(36);TOPICS[id]={id,title:d.title,tags:'',sub:s,chap:{t:'Übungen aus dem Netz',i:'🌐'},s:textToSlides(d.text,8).map(x=>[esc(x[0]),esc(x[1])]),ex:[],extra:[],vgen:g};go('#/practice/'+id)}
function onlineExPage(f,q){
  setNav('home');const s=subjById(f||'deutsch')||SUBJ[2],k=klasse();
  app().innerHTML=`<a class="back" href="#/s/${s.id}">← ${s.name}</a><h1>🌐 Übungen aus dem Netz</h1><p class="lead">Thema eingeben – die App holt einen Lexikon-Text und baut daraus <b>endlos</b> Lückentext-Aufgaben. Oder ein zufälliges Thema für ${s.name==='Englisch'?'englische Texte':'Allgemeinwissen'}.</p>
  <input id="oq" class="ans" placeholder="Thema, z. B. Mittelalter, Magnet, Herz" value="${esc(q||'')}"><div class="row2"><button id="ob" class="go">✏️ Übungen bauen</button><button id="or">🎲 Zufallsthema</button></div><div id="oout" class="hint"></div>`;
  const src=s.id==='englisch'?'simple':k<=7?'klexikon':'wiki';
  const run=async rnd=>{$('#oout').textContent='Lade Text …';try{let d=await wikiFetch(src,$('#oq').value.trim(),rnd);if(!d&&src==='klexikon'&&!rnd)d=await wikiFetch('wiki',$('#oq').value.trim());if(!d){$('#oout').textContent='Nichts gefunden.';return}startCloze(d,s)}catch(e){$('#oout').textContent='Keine Verbindung zum Internet?'}};
  $('#ob').onclick=()=>{if($('#oq').value.trim())run(false)};$('#or').onclick=()=>run(true);
}

/* ---------- Diktat ---------- */
function dictOffline(lang,k){
  if(lang==='en')return['My name is Tom and I live in London.','We have English on Monday and Tuesday.','There is a big tree in our garden.','My sister likes reading books.','Can you help me with my homework, please?','We went to the zoo last Saturday.','The weather is cold and windy today.','I usually get up at seven o\'clock.','Where are my trainers? They are under the bed.','He doesn\'t like vegetables, but he loves pizza.','Yesterday we played football in the park.','How much are the apples?','Would you like a cup of tea?','Our teacher is very friendly.','I am going to visit my grandparents next week.'];
  const a=['Im Sommer fahren wir mit dem Fahrrad an den See.','Der Hund bellt laut, weil er hungrig ist.','Meine Schwester liest gern spannende Bücher.','Am Wochenende besuchen wir unsere Großeltern.','Ich weiß, dass du morgen Geburtstag hast.','Das Wasser im Fluss fließt sehr schnell.','Wir müssen die Hausaufgaben bis Montag erledigen.','Der Lehrer erklärt die Aufgabe noch einmal.','Im Winter ist es draußen kalt und dunkel.','Nach dem Essen spielen die Kinder im Garten.','Die Straße ist nass, denn es hat geregnet.','Mein Bruder hat sich ein neues Spiel gewünscht.','Das Mädchen fährt mit dem Zug in die Stadt.','Am Abend ist der Himmel voller Sterne.','Wir haben viel Spaß beim Schwimmen gehabt.'];
  const b=['Obwohl es stark regnete, gingen wir spazieren.','Die Wissenschaftlerin erklärte, dass das Experiment gelungen sei.','Nachdem er den Brief gelesen hatte, rief er sofort an.','Das Ergebnis der Umfrage überraschte alle Beteiligten.','Wer rechtzeitig lernt, braucht sich vor der Prüfung nicht zu fürchten.','Die Mannschaft trainierte täglich, um das Endspiel zu gewinnen.','Im Allgemeinen ist das Wetter im Herbst wechselhaft.','Beim Lesen des Romans vergaß sie die Zeit.','Es ist wichtig, die Umwelt zu schützen und Müll zu vermeiden.','Die Abgeordneten diskutierten lange über das neue Gesetz.'];
  return k<=7?a:a.concat(b)}
function dictatPage(id){
  setNav('home');let lang='de',srcName='',sents=[],s=SUBJ[2];
  const t=id&&TOPICS[id],it=t&&t.mine&&MINE.find(x=>x.id===t.mine);
  if(it){s=SUBJ[it.s];lang=it.s===1?'en':'de';sents=(it.dict||[]).slice();if(!sents.length)sents=sentencesOf(it.text);srcName=it.name}
  else{if(id==='englisch'){s=SUBJ[1];lang='en'}srcName=s.name}
  const L=lang==='en'?'en-GB':'de-DE',k=klasse(),st={i:0,ok:0,n:0,q:shuffle(sents),chunk:0};
  const more=async()=>{try{const d=await wikiFetch(lang==='en'?'simple':k<=7?'klexikon':'wiki','',true);if(d){const add=sentencesOf(d.text).filter(x=>{const w=x.split(' ').length;return w>=5&&w<=(k<=7?12:18)&&!/[0-9()\[\]"„“:;]/.test(x)});st.q=st.q.concat(shuffle(add).slice(0,6))}}catch(e){}if(st.q.length<=st.i)st.q=st.q.concat(shuffle(dictOffline(lang,k)))};
  const draw=async()=>{if(st.i>=st.q.length){app().innerHTML='<p class="lead">Lade neue Sätze …</p>';await more()}
    const x=st.q[st.i],parts=[];const w=x.split(' ');for(let n=0;n<w.length;n+=3)parts.push(w.slice(n,n+3).join(' '));st.chunk=0;
    app().innerHTML=`<a class="back" href="${it?'#/t/'+id:'#/s/'+s.id}">← Ende</a><h1>✍️ Diktat – ${esc(srcName)}</h1><div class="vprog">Satz ${st.n+1} · ${st.ok} fehlerfrei</div>
    <div class="qcard"><div class="row2"><button id="dp" class="go">🔊 Ganzer Satz</button><button id="dc">🐢 Stück für Stück (${parts.length})</button></div>
    <textarea id="din" class="ans" rows="3" autocomplete="off" autocapitalize="sentences" spellcheck="false" placeholder="Schreibe den Satz genau auf – mit Punkt und Großschreibung."></textarea><button id="dk" class="go">✔ Prüfen</button><div id="dfb"></div></div>
    <p class="hint">${it?'Sätze aus deiner Sache.':'Sätze aus dem '+(lang==='en'?'Simple-English-Wikipedia':k<=7?'Kinderlexikon':'Lexikon')+' oder aus der App – immer neue.'}</p>`;
    $('#dp').onclick=()=>speak(x,L);$('#dc').onclick=()=>{speak(parts[st.chunk%parts.length],L);st.chunk++};setTimeout(()=>speak(x,L),300);
    $('#dk').onclick=()=>{const a=$('#din').value.trim().replace(/\s+/g,' ');if(!a)return;const sol=x.split(' '),inp=a.split(' ');let err=0;
      const h=sol.map((wd,n)=>{const ok=inp[n]===wd;if(!ok)err++;return ok?esc(wd):`<b style="color:#dc2626;text-decoration:underline">${esc(wd)}</b>`}).join(' ');if(inp.length>sol.length)err+=inp.length-sol.length;
      st.n++;if(!err)st.ok++;$('#dfb').innerHTML=`<div class="fb ${err?'no':'ok'}"><b>${err?err+' Fehler':pick(PRAISE)+' Fehlerfrei!'}</b><br>${h}</div><button id="dnx" class="go">Nächster Satz ▶</button>`;$('#dk').disabled=true;$('#dnx').onclick=()=>{st.i++;draw()}};};
  draw()}

